#include <GLES2/gl2.h>
#include <EGL/egl.h>
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <time.h>
extern int lrGPUGetStatistics(uint64_t*,uint64_t*,uint64_t*);
static double clock_ns(void){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec*1e9+t.tv_nsec;}
int main(void){setbuf(stdout,NULL);EGLDisplay d=eglGetDisplay(NULL);assert(eglInitialize(d,NULL,NULL));EGLConfig config;EGLint n;assert(eglChooseConfig(d,NULL,&config,1,&n));EGLint attributes[]={EGL_WIDTH,32,EGL_HEIGHT,32,EGL_NONE},version[]={EGL_CONTEXT_CLIENT_VERSION,2,EGL_NONE};EGLSurface surface=eglCreatePbufferSurface(d,config,attributes);EGLContext context=eglCreateContext(d,config,NULL,version);assert(context&&surface&&eglMakeCurrent(d,surface,surface,context));GLuint texture,fb;glGenTextures(1,&texture);glBindTexture(GL_TEXTURE_2D,texture);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,512,512,0,GL_RGBA,GL_UNSIGNED_BYTE,NULL);glGenFramebuffers(1,&fb);glBindFramebuffer(GL_FRAMEBUFFER,fb);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,texture,0);assert(glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE);glViewport(0,0,512,512);glClearColor(0,1,0,1);for(int i=0;i<10;i++){glClear(GL_COLOR_BUFFER_BIT);glFinish();}uint64_t before,reads,ns;assert(lrGPUGetStatistics(&before,&reads,&ns));for(int run=0;run<5;run++){uint64_t n0=ns;double start=clock_ns();for(int i=0;i<100;i++){glClear(GL_COLOR_BUFFER_BIT);glFinish();}double time=clock_ns()-start;uint64_t after;assert(lrGPUGetStatistics(&after,&reads,&ns));unsigned char p[4];glReadPixels(250,250,1,1,GL_RGBA,GL_UNSIGNED_BYTE,p);assert(p[0]==0&&p[1]==255&&p[2]==0&&!glGetError());printf("FBO_COPY_BENCH repeat=%d copies=100 bytes=104857600 milliseconds=%.3f gpu_ns=%llu pixel=PASS\n",run+1,time/1e6,(unsigned long long)(ns-n0));}glBindFramebuffer(GL_FRAMEBUFFER,0);glDeleteFramebuffers(1,&fb);glDeleteTextures(1,&texture);eglMakeCurrent(d,NULL,NULL,NULL);assert(eglDestroyContext(d,context)&&eglDestroySurface(d,surface));return 0;}
